ST.xhtml:
parts.timing(
    operator_ref := operator_ref,
    config_ref := config.timing,
    longitude_ref := config.longitude,
    latitude_ref := config.latitude,
    height_ref := config.height);
parts.mercatorMeteo( config_ref := config.mercatorMeteo );
parts.configManager( isEnabled := operator_ref = OperatorStatus.tech );
stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := ((parts.timing.stat.health = HealthStatus.good) OR (parts.timing.stat.health = HealthStatus.warning)) AND ((parts.mercatorMeteo.stat.health = HealthStatus.good) OR (parts.mercatorMeteo.stat.health = HealthStatus.warning)),
    hasWarning := (parts.timing.stat.health = HealthStatus.warning) OR (parts.mercatorMeteo.stat.health = HealthStatus.warning));
stat.busy := F_BusyStatus(
    superState := TRUE,
    isBusy := stat.init = InitializationStatus.initializing);
proc.initialize( isEnabled := (stat.init = InitializationStatus.shutdown) OR ((stat.init = InitializationStatus.initializingFailed) OR (stat.init = InitializationStatus.initialized)) );
proc.lock( isEnabled := (operator_ref = OperatorStatus.tech) AND (stat.init = InitializationStatus.initialized) );
proc.unlock( isEnabled := (operator_ref = OperatorStatus.tech) AND (stat.init = InitializationStatus.locked) );
proc.changeOperatingState( isEnabled := FALSE );

stat.health := F_HealthStatus(
    superState := TRUE,
    hasWarning := FALSE,
    isGood := config_ref.alwaysUseLocalClock OR (isNtpConnected AND isNtpSynchronized));
sysTime_ro := sysTime;
ntpExtTime_ro := ntpExtTime;
ntpLastUpdated_ro := ntpLastUpdated;
sysToNtpExtTimeOffset_ro := sysToNtpExtTimeOffset;
isNtpConnected_ro := isNtpConnected;
isNtpSynchronized_ro := isNtpSynchronized;
